  create_view "affectionate_briars_6712.entity_aggregated_tag_list", <<-SQL
     SELECT e.id AS entity_id,
    string_agg((t.name)::text, ','::text) AS tag_list
   FROM affectionate_briars_6712.entities e,
    affectionate_briars_6712.tags t,
    affectionate_briars_6712.taggings e_t
  WHERE ((e.id = e_t.taggable_id) AND (e_t.tag_id = t.id))
  GROUP BY e.id;
  SQL
